using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;
public sealed class CPCProbe:MonoBehaviour {
 [Serializable]public class Row{public string name,status,detail;}
 [Serializable]class Report{public string layer,error;public bool baseline;public Row[] rows;}
 [Serializable]class DeathAudit{public string name,entity,globalBefore,globalAfter,localBefore,localAfter,bagBefore,bagAfter;public float hpBefore,hpAfter;public int attacks,completedBefore,completedAfter;public string[] dropIds;}
 [Serializable]class RestartAudit{public string name,oldScene,newScene;public int oldMaterials,remainingOldMaterials,contexts,eventHandlers;public bool oldActorsGone;}
 public static bool Done;public static int Code;public bool formal;
 public string Root{get;private set;}public bool Baseline=>typeof(CombatEnemy).Assembly.GetType("TrainingLootContext")==null;
 readonly List<Row> rows=new List<Row>();double deadline;bool finished;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();if(Array.IndexOf(a,"-cp05-c")<0)return;var g=new GameObject("CP05C isolated regression probe");DontDestroyOnLoad(g);g.AddComponent<CPCProbe>().formal=Array.IndexOf(a,"-cpc-formal")>=0;}
 IEnumerator Start(){Root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);deadline=Time.realtimeSinceStartupAsDouble+240;Application.runInBackground=true;Application.logMessageReceived+=Log;var stack=new Stack<IEnumerator>();stack.Push(formal?CPCFormal.Run(this):Training());while(stack.Count>0){bool next=false;object current=null;try{next=stack.Peek().MoveNext();if(next)current=stack.Peek().Current;}catch(Exception e){Finish(e.ToString());yield break;}if(!next){stack.Pop();continue;}if(current is IEnumerator sub){stack.Push(sub);continue;}yield return current;}Finish(null);}
 public void Check(string name,bool ok,string detail){var r=new Row{name=name,status=ok?"PASS":"FAIL",detail=detail};rows.Add(r);File.AppendAllText(Root+"/progress.jsonl",JsonUtility.ToJson(r)+"\n");}
 void Log(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error)File.AppendAllText(Root+"/runtime-errors.txt",message+"\n"+stack+"\n");}
 void Update(){if(!finished&&Time.realtimeSinceStartupAsDouble>deadline)Finish("Bounded runtime deadline");}
 public static string Rng()=>JsonUtility.ToJson(UnityEngine.Random.state);
 public static string Bag(ThirdPersonHero h)=>JsonUtility.ToJson(new BagData{gear=h.GetComponent<AdventureLoadout>().items.ToArray(),materials=h.Inventory.Materials.ToArray(),potions=h.Inventory.HealthPotionCount});
 [Serializable]class BagData{public GearItem[] gear;public MaterialStack[] materials;public int potions;}
 public static object Field(object owner,string name)=>owner.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(owner);
 public static int ContextCount(){var t=typeof(CombatEnemy).Assembly.GetType("TrainingLootContext");return t==null?-1:(int)t.GetProperty("ActiveCount").GetValue(null);}
 public static Component Context(ThirdPersonHero h){var t=typeof(CombatEnemy).Assembly.GetType("TrainingLootContext");return t==null?null:UnityEngine.Object.FindObjectsByType(t,FindObjectsSortMode.None).Cast<Component>().FirstOrDefault(c=>c.gameObject.scene==h.gameObject.scene);}
 public static string Streams(Component c)=>c==null?"MISSING":(string)c.GetType().GetProperty("RandomFingerprint").GetValue(c);
 public static int Completed(Component c)=>c==null?-1:(int)c.GetType().GetProperty("CompletedDeaths").GetValue(c);
 public static int Handlers(object target){return typeof(SceneManager).GetFields(BindingFlags.Static|BindingFlags.NonPublic).Where(f=>typeof(Delegate).IsAssignableFrom(f.FieldType)).Select(f=>f.GetValue(null) as Delegate).Where(d=>d!=null).Sum(d=>d.GetInvocationList().Count(x=>ReferenceEquals(x.Target,target)));}
 public static string Ledger(string root){var files=new List<string>();foreach(string directory in new[]{"WanxiangGuitu/ForestRuins","Legacy/ForestRuins"}){string p=Path.Combine(root,directory);if(Directory.Exists(p))files.AddRange(Directory.GetFiles(p,"*",SearchOption.AllDirectories));}return string.Join("\n",files.OrderBy(f=>f,StringComparer.Ordinal).Select(f=>f.Substring(root.Length+1).Replace('\\','/')+"="+BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(File.ReadAllBytes(f))).Replace("-","").ToLowerInvariant()));}
 public IEnumerator Wait(Func<bool> predicate,float seconds){float end=Time.realtimeSinceStartup+seconds;while(!predicate()&&Time.realtimeSinceStartup<end)yield return null;}
 public IEnumerator Reopen(string name){var host=CP05Training.Instance;var old=host.Hero;var scene=old.gameObject.scene;var enemies=host.Enemies.ToArray();var mats=((IEnumerable<Material>)Field(host,"ownedMaterials")).ToArray();string rng=Rng();var button=UnityEngine.Object.FindObjectsByType<Button>().Single(b=>b.GetComponentInChildren<Text>()?.text=="重开训练");button.onClick.Invoke();yield return Wait(()=>host.Hero!=null&&host.Hero!=old&&!scene.isLoaded,3);yield return null;yield return null;
  bool changed=host.Hero!=null&&host.Hero!=old&&!scene.isLoaded;Check(name,changed,"actual button callback + scene unload/new instance");Check(name+"-old-actors",changed&&enemies.All(e=>e==null),"old scene actors destroyed");Check(name+"-old-materials",changed&&mats.All(m=>m==null),"explicitly owned world materials destroyed; shared resource materials excluded");Check(name+"-rng",Rng()==rng,"Unity global unchanged by restart");if(changed){Check(name+"-context",ContextCount()==1,"one transient registered scene");Check(name+"-eventsystem",UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>().Count(e=>e.gameObject.scene==host.Hero.gameObject.scene)==1,"one own UI EventSystem");Check(name+"-one-event-subscription",Handlers(host)==1,"single launcher scene-unloaded subscription");}File.AppendAllText(Root+"/restarts.jsonl",JsonUtility.ToJson(new RestartAudit{name=name,oldScene=scene.handle.ToString(),newScene=host.Hero==null?"NONE":host.Hero.gameObject.scene.handle.ToString(),oldMaterials=mats.Length,remainingOldMaterials=mats.Count(m=>m!=null),contexts=ContextCount(),eventHandlers=Handlers(host),oldActorsGone=enemies.All(e=>e==null)})+"\n");}
 IEnumerator Training(){yield return Wait(()=>CP05Training.Instance?.Hero!=null,15);if(CP05Training.Instance?.Hero==null)throw new Exception("Training not ready");yield return null;yield return null;Check("no-formal-session",UnityEngine.Object.FindObjectsByType<CombatSession>().Length==0,"training has no synthetic/fake CombatSession or Wave");string canary=File.Exists(Root+"/canary-before.txt")?File.ReadAllText(Root+"/canary-before.txt").Replace("\r\n","\n").TrimEnd('\r','\n'):Ledger(Root);Check("save-canary-initial",canary==Ledger(Root),"genuine isolated checkpoint bytes unchanged by training entry");
  // First expose real weapon death on baseline, before a broken restart can block the fixture.
  if(Baseline){int seed=1;for(;seed<100;seed++){UnityEngine.Random.InitState(seed);if(UnityEngine.Random.value<.4f)break;}UnityEngine.Random.InitState(seed);yield return Kill(CP05Training.Instance.Enemies[0],"baseline-death");yield return Reopen("restart-1");yield return Reopen("restart-2");yield return Reopen("restart-3");yield break;}
  yield return Reopen("restart-1");yield return Reopen("restart-2");yield return Reopen("restart-3");
  var h=CP05Training.Instance.Hero;h.Inventory.SetOpen(true);Check("paused-before-restart",h.GameplayPaused,"normal inventory UI pause");yield return Reopen("paused-restart");Check("new-instance-unpaused",!CP05Training.Instance.Hero.GameplayPaused&&Time.timeScale>0,"new factory instance, no direct health/reset/inventory writes");
  // Genuine scene-name collision fault. Product must not unload this foreign collision scene.
  var host=CP05Training.Instance;h=host.Hero;var ctx=Context(h);string bag=Bag(h),random=Rng(),local=Streams(ctx);float health=h.Health.Current;string next=(string)host.GetType().GetProperty("NextSceneName").GetValue(host);var conflict=SceneManager.CreateScene(next);var current=h.gameObject.scene;host.GetType().GetMethod("RequestRestart").Invoke(host,null);yield return Wait(()=>!(bool)host.GetType().GetProperty("Restarting").GetValue(host),3);Check("collision-fault-preserves-old",host.Hero==h&&current.isLoaded&&h.gameObject.activeInHierarchy,"real CreateScene collision, old arena preserved");Check("collision-fault-preserves-state",bag==Bag(h)&&random==Rng()&&local==Streams(ctx)&&health==h.Health.Current,"old life/bag/global+local RNG unchanged");Check("foreign-collision-scene-preserved",conflict.isLoaded,"never unload a scene this transaction did not create");yield return SceneManager.UnloadSceneAsync(conflict);yield return Reopen("retry-after-failure");
  for(int i=0;i<6;i++){h=CP05Training.Instance.Hero;CombatEnemy e;if(i<2)e=CP05Training.Instance.Enemies[i];else{e=Instantiate(Resources.Load<GameObject>("CP05Training/Enemy"),new Vector3(0,.15f,2),Quaternion.identity).GetComponent<CombatEnemy>();e.entityId="cp05c-extra:"+i;e.target=h;}yield return Kill(e,"death-"+i);}
  Check("real-equipment-drops-exercised",UnityEngine.Object.FindObjectsByType<LootPickup>().Any(l=>l.Gear!=null),"natural chance, no injected rewards; failure retained if no equipment sample");
  yield return Reopen("before-player-death");h=CP05Training.Instance.Hero;var startHealth=h.Health.Current;var existing=CP05Training.Instance.Enemies;for(int i=0;i<8;i++){var e=i<2?existing[i]:Instantiate(Resources.Load<GameObject>("CP05Training/Enemy"),Vector3.zero,Quaternion.identity).GetComponent<CombatEnemy>();var cc=e.GetComponent<CharacterController>();cc.enabled=false;float a=i*Mathf.PI*.25f;e.transform.position=h.transform.position+new Vector3(Mathf.Sin(a)*1.4f,.1f,Mathf.Cos(a)*1.4f);cc.enabled=true;e.target=h;}
  yield return Wait(()=>h.Health.Dead,55);Check("real-ai-player-death",h.Health.Dead&&h.Health.Current<startHealth,"unchanged enemy attacks, no Damage injection");if(h.Health.Dead)yield return Reopen("death-restart");
  var oldHost=CP05Training.Instance;var oldScene=oldHost.Hero.gameObject.scene;yield return SceneManager.LoadSceneAsync(GameEntry.TitlePath);yield return null;yield return null;Check("external-unload-disposes-host",CP05Training.Instance==null&&!oldScene.isLoaded&&ContextCount()==0,"no DDOL host/registry left after unload");Check("external-unload-removes-event",Handlers(oldHost)==0,"old host not retained by scene events");CP05Training.StartIsolated();yield return Wait(()=>CP05Training.Instance?.Hero!=null,10);Check("reenter-training",CP05Training.Instance?.Hero!=null&&ContextCount()==1,"fresh owned scene/context after unload");Check("save-canary-final",canary==Ledger(Root),"entry/restarts/deaths/unload/reentry did not modify existing synthetic v9 save");
  yield return new WaitForEndOfFrame();var tex=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Root+"/training.png",tex.EncodeToPNG());Destroy(tex);
 }
 public IEnumerator Kill(CombatEnemy e,string name){var h=CP05Training.Instance!=null?CP05Training.Instance.Hero:e.target;foreach(var other in UnityEngine.Object.FindObjectsByType<CombatEnemy>())if(other!=e)other.enabled=false;var cc=e.GetComponent<CharacterController>();cc.enabled=false;e.transform.position=h.transform.position+Vector3.forward*1.35f;cc.enabled=true;e.enabled=true;e.target=h;h.transform.rotation=Quaternion.identity;var cam=h.cameraTransform.GetComponent<OrbitCamera>();cam.enabled=false;h.cameraTransform.position=h.transform.position+new Vector3(0,4,-5);h.cameraTransform.LookAt(e.transform.position+Vector3.up);var combat=h.GetComponent<AdventureCombat>();var sword=combat.Gear.items.First(x=>x.type==GearType.Sword&&x.InBag);combat.Gear.SelectMain(sword);PlayerInput.Focus(true);yield return null;yield return null;float hp=e.Health.Current;int accepted=0;float end=Time.realtimeSinceStartup+12;
  string originalGlobal=Rng(),originalBag=Bag(h),originalLocal=Streams(Context(h));int originalCompleted=Completed(Context(h));
  while(!e.Health.Dead&&Time.realtimeSinceStartup<end){if(h.Progression.IsChoosing)h.Progression.SelectChoice(0);if(combat.Strike())accepted++;yield return null;}
  yield return null;yield return null;Check(name+"-real-death",e.Health.Dead&&accepted>0&&e.Health.Current<hp,"actual Strike -> MeleeGeometry -> health/death path accepted="+accepted);int drops=UnityEngine.Object.FindObjectsByType<LootPickup>().Length;float xp=h.Progression.Experience;string global=Rng(),bag=Bag(h);var ctx=Context(h);string local=Streams(ctx);int complete=Completed(ctx);for(int i=0;i<5;i++)e.DropLootOnce();Check(name+"-unique",drops==UnityEngine.Object.FindObjectsByType<LootPickup>().Length&&xp==h.Progression.Experience&&bag==Bag(h)&&global==Rng()&&local==Streams(ctx),"five repeated death requests did not award/spend/draw again");Check(name+"-context-completed",ctx!=null&&complete==originalCompleted+1,"one actual training death completed exactly once");Check(name+"-global-isolated",originalGlobal==global,"death/level-up rolls do not consume Unity global");Check(name+"-bag-unchanged",originalBag==bag,"ground drops do not pre-credit bag");File.AppendAllText(Root+"/deaths.jsonl",JsonUtility.ToJson(new DeathAudit{name=name,entity=e.entityId,globalBefore=originalGlobal,globalAfter=global,localBefore=originalLocal,localAfter=local,bagBefore=originalBag,bagAfter=bag,hpBefore=hp,hpAfter=e.Health.Current,attacks=accepted,completedBefore=originalCompleted,completedAfter=complete,dropIds=UnityEngine.Object.FindObjectsByType<LootPickup>().Select(l=>l.Gear?.id??l.InteractionId).ToArray()})+"\n");
 }
 void Finish(string error){if(finished)return;finished=true;Application.logMessageReceived-=Log;if(error!=null)Check("probe-exception",false,error);Code=rows.Any(r=>r.status=="FAIL")?1:0;File.WriteAllText(Root+"/probe.json",JsonUtility.ToJson(new Report{layer=Application.isEditor?"controlled Editor API":"isolated nondevelopment Player API",baseline=Baseline,error=error,rows=rows.ToArray()},true));Done=true;if(!Application.isEditor)Application.Quit(Code);}
}
